/**
 * Villes du Sénégal — niveau « commune », l'échelon administratif de base
 * (collectivité territoriale). 552 communes, réparties sur 14 régions
 * et 46 départements.
 *
 * Coordonnées : chef-lieu de la commune (WGS 84, degrés décimaux).
 * Source : recensement ANSD 2023 / limites GADM.
 *
 * `departement` et `region` ne sont pas persistés — le schéma Prisma s'arrête
 * au couple Pays → Ville. Ils documentent le rattachement administratif et
 * justifient le suffixe des trois communes homonymes (Dinguiraye,
 * Medina Gounass, Missirah), que la contrainte @@unique([nom, paysId])
 * interdirait sinon de distinguer.
 *
 * Fichier de données pur — aucune logique métier.
 */

export interface VilleData {
  readonly nom: string;
  readonly latitude: number;
  readonly longitude: number;
  readonly departement: string;
  readonly region: string;
}

